def die(msg, code=1):
    sys.stderr.write(str(msg))
    if not str(msg).endswith('\n'):
        sys.stderr.write('\n')
    raise SystemExit(code)


def invalid_args(cmd):
    sys.stderr.write("Invalid arguments.\n\n")
    print_cmd_usage_err(cmd)
    raise SystemExit(1)


def print_cmd_usage_err(cmd):
    usages = {
        'select': 'Usage:\n    xsv select [options] [--] <selection> [<input>]\n    xsv select --help\n',
        'cat': 'Usage:\n    xsv cat rows    [options] [<input>...]\n    xsv cat columns [options] [<input>...]\n    xsv cat --help\n',
        'join': 'Usage:\n    xsv join [options] <columns1> <input1> <columns2> <input2>\n    xsv join --help\n',
        'partition': 'Usage:\n    xsv partition [options] <column> <outdir> [<input>]\n    xsv partition --help\n',
        'sample': 'Usage:\n    xsv sample [options] <sample-size> [<input>]\n    xsv sample --help\n',
        'split': 'Usage:\n    xsv split [options] <outdir> [<input>]\n    xsv split --help\n',
    }
    sys.stderr.write(usages.get(cmd, 'Usage:\n    xsv %s [options] [<input>]\n' % cmd))


def decode_char(s, opt='value'):
    m = {'\\t':'\t', '\\n':'\n', '\\r':'\r', '\\0':'\0'}
    if s in m:
        s = m[s]
    if len(s) != 1 or ord(s) > 127:
        die("Could not convert '%s' to a single ASCII character." % s)
    return s


def parse_opts(argv, specs, cmd=None, stop_at_double=True):
    """Permissive docopt-like option scanner. specs maps option to (key, takes_value)."""
    opts = {}
    pos = []
    i = 0
    stop = False
    while i < len(argv):
        a = argv[i]
        if not stop and a == '--' and stop_at_double:
            stop = True; i += 1; continue
        if not stop and a in ('-h','--help'):
            opts['help'] = True; i += 1; continue
        if not stop and a.startswith('--') and len(a) > 2:
            if '=' in a:
                name, val = a.split('=',1)
            else:
                name, val = a, None
            if name not in specs:
                sys.stderr.write("Unknown flag: '%s'\n\n" % name)
                if cmd: print_cmd_usage_err(cmd)
                raise SystemExit(1)
            key, takes = specs[name]
            if takes:
                if val is None:
                    i += 1
                    if i >= len(argv): invalid_args(cmd or '')
                    val = argv[i]
                opts[key] = val
            else:
                if val is not None:
                    opts[key] = val
                else:
                    opts[key] = True
            i += 1; continue
        if not stop and a.startswith('-') and a != '-':
            # only exact short options are supported; negative numbers remain flags like docopt
            if a not in specs:
                sys.stderr.write("Unknown flag: '%s'\n\n" % a)
                if cmd: print_cmd_usage_err(cmd)
                raise SystemExit(1)
            key, takes = specs[a]
            if takes:
                i += 1
                if i >= len(argv): invalid_args(cmd or '')
                opts[key] = argv[i]
            else:
                opts[key] = True
            i += 1; continue
        pos.append(a); i += 1
    return opts, pos

COMMON_SPECS = {
    '-o': ('output', True), '--output': ('output', True),
    '-n': ('no_headers', False), '--no-headers': ('no_headers', False),
    '-d': ('delimiter', True), '--delimiter': ('delimiter', True),
}

def common_specs(extra=None, include_output=True, include_no_headers=True):
    s = {}
    for k,v in COMMON_SPECS.items():
        if not include_output and v[0]=='output': continue
        if not include_no_headers and v[0]=='no_headers': continue
        s[k]=v
    if extra:
        s.update(extra)
    return s


def input_handle(path):
    if path is None or path == '-':
        return sys.stdin, False
    try:
        return open(path, newline='', encoding='utf-8'), True
    except OSError as e:
        die(str(e))


def read_csv(path=None, delimiter=',', quotechar='"', escapechar=None, quoting=True):
    fh, close = input_handle(path)
    try:
        q = csv.QUOTE_MINIMAL if quoting else csv.QUOTE_NONE
        qc = quotechar if quoting else None
        rdr = csv.reader(fh, delimiter=delimiter, quotechar=qc, escapechar=escapechar, doublequote=(escapechar is None), quoting=q)
        return [list(r) for r in rdr]
    except csv.Error as e:
        die('CSV error: %s' % e)
    finally:
        if close: fh.close()


def output_handle(path):
    if path:
        try: return open(path, 'w', newline='', encoding='utf-8'), True
        except OSError as e: die(str(e))
    return sys.stdout, False


def write_csv(rows, output=None, delimiter=',', terminator='\n', quotechar='"', escapechar=None, quote_always=False):
    fh, close = output_handle(output)
    try:
        writer = csv.writer(fh, delimiter=delimiter, quotechar=quotechar, escapechar=escapechar,
                            doublequote=(escapechar is None), lineterminator=terminator,
                            quoting=(csv.QUOTE_ALL if quote_always else csv.QUOTE_MINIMAL))
        for row in rows:
            writer.writerow(['' if x is None else str(x) for x in row])
    finally:
        if close: fh.close()


def split_header(rows, no_headers=False):
    if not rows:
        return None, []
    if no_headers:
        return None, rows
    return rows[0], rows[1:]


def effective_len(row):
    n = len(row)
    while n > 1 and row[n-1] == '':
        n -= 1
    return max(1, n)


def parse_int(s, name='value', signed=False):
    try:
        if not signed and str(s).startswith('-'):
            raise ValueError
        return int(s)
    except Exception:
        if name.startswith('--'):
            die("Could not deserialize '%s' to u64 for '%s'." % (s, name))
        die("Could not convert '%s' to an integer." % s)


def tokenize_selection(sel):
    toks = []
    cur = ''
    inq = False
    i = 0
    while i < len(sel):
        ch = sel[i]
        if inq:
            if ch == '"':
                if i+1 < len(sel) and sel[i+1] == '"':
                    cur += '"'; i += 2; continue
                inq = False; i += 1; continue
            cur += ch; i += 1; continue
        else:
            if ch == '"':
                inq = True; i += 1; continue
            if ch == ',':
                toks.append(cur); cur=''; i += 1; continue
            cur += ch; i += 1
    toks.append(cur)
    return [t for t in toks if t != '']


def is_index_token(t):
    return re.fullmatch(r'[0-9]+', t or '') is not None


def name_index_token(t):
    m = re.fullmatch(r'(.+)\[([0-9]+)\]', t or '')
    if m:
        return m.group(1), int(m.group(2))
    return t, 0


def resolve_one(tok, headers, ncols, no_headers):
    if is_index_token(tok):
        idx = int(tok)
        if idx < 1 or idx > ncols:
            die("Selector index %s is out of bounds. Index must be >= 1 and <= %s." % (idx, ncols))
        return idx - 1
    if no_headers:
        die("Cannot use names ('%s') in selection with --no-headers set." % tok)
    name, occ = name_index_token(tok)
    matches = [i for i,h in enumerate(headers or []) if h == name]
    if not matches:
        die("Selector name '%s' does not exist as a named header in the given CSV data." % name)
    if occ < 0 or occ >= len(matches):
        die("Selector index '%s' for name '%s' is out of bounds. Must be >= 0 and <= %s." % (occ, name, len(matches)-1))
    return matches[occ]


def find_range_dash(tok):
    inq = False
    for i,ch in enumerate(tok):
        if ch == '"': inq = not inq
        elif ch == '-' and not inq:
            return i
    return -1


def parse_selection(sel, headers, ncols, no_headers=False):
    invert = False
    if sel.startswith('!'):
        invert = True; sel = sel[1:]
    out = []
    for tok in tokenize_selection(sel):
        dash = find_range_dash(tok)
        if dash >= 0:
            a, b = tok[:dash], tok[dash+1:]
            start = 0 if a == '' else resolve_one(a, headers, ncols, no_headers)
            end = ncols-1 if b == '' else resolve_one(b, headers, ncols, no_headers)
            step = 1 if start <= end else -1
            out.extend(range(start, end + step, step))
        else:
            out.append(resolve_one(tok, headers, ncols, no_headers))
    if invert:
        s = set(out)
        out = [i for i in range(ncols) if i not in s]
    return out


def row_get(row, i):
    return row[i] if i < len(row) else ''


def cmd_count(argv):
    opts,pos = parse_opts(argv, common_specs(include_output=False), 'count')
    if opts.get('help'): return print_cmd_help('count')
    if len(pos)>1: invalid_args('count')
    delim = decode_char(opts.get('delimiter', ','))
    rows = read_csv(pos[0] if pos else None, delim)
    n = len(rows) if opts.get('no_headers') else max(0, len(rows)-1)
    sys.stdout.write(str(n)+'\n')


def cmd_headers(argv):
    opts,pos = parse_opts(argv, common_specs({'-j':('just_names',False),'--just-names':('just_names',False),'--intersect':('intersect',False)}, include_output=False, include_no_headers=False), 'headers')
    if opts.get('help'): return print_cmd_help('headers')
    delim=decode_char(opts.get('delimiter',','))
    if not pos: pos=[None]
    headers=[]
    for p in pos:
        rows=read_csv(p,delim)
        if rows: headers.append(rows[0])
        else: headers.append([])
    just = opts.get('just_names') or len(pos)>1 or opts.get('intersect')
    if opts.get('intersect'):
        # observed behavior is de-duplicated union in first-seen order
        seen=set(); vals=[]
        for hs in headers:
            for h in hs:
                if h not in seen:
                    seen.add(h); vals.append(h)
        for h in vals: print(h)
    elif just:
        for hs in headers:
            for h in hs: print(h)
    else:
        if headers:
            for i,h in enumerate(headers[0],1):
                sys.stdout.write('%-4s%s\n' % (str(i), h))


def cmd_select(argv):
    opts,pos = parse_opts(argv, common_specs(), 'select')
    if opts.get('help'): return print_cmd_help('select')
    if len(pos)<1 or len(pos)>2: invalid_args('select')
    sel,path = pos[0], (pos[1] if len(pos)>1 else None)
    delim=decode_char(opts.get('delimiter',','))
    rows=read_csv(path,delim)
    if not rows: return
    headers,data=split_header(rows, opts.get('no_headers'))
    ncols=max([len(r) for r in rows] or [0])
    if headers is not None: ncols=len(headers)
    idxs=parse_selection(sel, headers, ncols, bool(opts.get('no_headers')))
    out=[]
    if headers is not None: out.append([row_get(headers,i) for i in idxs])
    for r in data: out.append([row_get(r,i) for i in idxs])
    write_csv(out, opts.get('output'))


def cmd_slice(argv):
    specs=common_specs({'-s':('start',True),'--start':('start',True),'-e':('end',True),'--end':('end',True),'-l':('len',True),'--len':('len',True),'-i':('index',True),'--index':('index',True)})
    opts,pos=parse_opts(argv,specs,'slice')
    if opts.get('help'): return print_cmd_help('slice')
    if len(pos)>1: invalid_args('slice')
    rows=read_csv(pos[0] if pos else None, decode_char(opts.get('delimiter',',')))
    header,data=split_header(rows, opts.get('no_headers'))
    out=[]
    if header is not None: out.append(header)
    if 'index' in opts:
        start=parse_int(opts['index'],'--index'); end=start+1
    else:
        start=parse_int(opts.get('start','0'),'--start') if 'start' in opts else 0
        if 'end' in opts and 'len' in opts:
            if out: write_csv(out, opts.get('output'))
            die('--end and --len cannot be used at the same time.')
        if 'len' in opts:
            ln=parse_int(opts['len'],'--len'); end=start+ln
        elif 'end' in opts:
            end=parse_int(opts['end'],'--end')
        else:
            end=len(data)
    if end < start:
        if out: write_csv(out, opts.get('output'))
        die('The end of the range (%s) must be greater than or\nequal to the start of the range (%s).' % (end,start))
    if 'index' in opts and start >= len(data):
        if out: write_csv(out, opts.get('output'))
        die('invalid record index %s (there are %s records)' % (start, len(data)))
    out.extend(data[start:end])
    write_csv(out, opts.get('output'))


def cmd_reverse(argv):
    opts,pos=parse_opts(argv,common_specs(),'reverse')
    if opts.get('help'): return print_cmd_help('reverse')
    if len(pos)>1: invalid_args('reverse')
    rows=read_csv(pos[0] if pos else None, decode_char(opts.get('delimiter',',')))
    h,d=split_header(rows, opts.get('no_headers'))
    out=[]
    if h is not None: out.append(h)
    out.extend(reversed(d))
    write_csv(out, opts.get('output'))


def cmd_search(argv):
    specs=common_specs({'-i':('ignore_case',False),'--ignore-case':('ignore_case',False),'-s':('select',True),'--select':('select',True),'-v':('invert',False),'--invert-match':('invert',False)})
    opts,pos=parse_opts(argv,specs,'search')
    if opts.get('help'): return print_cmd_help('search')
    if len(pos)<1 or len(pos)>2: invalid_args('search')
    pattern,path=pos[0],(pos[1] if len(pos)>1 else None)
    flags=re.I if opts.get('ignore_case') else 0
    try: rx=re.compile(pattern, flags)
    except re.error as e: die('Syntax(\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nregex parse error:\n    %s\nerror: %s\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n)' % (pattern, e))
    rows=read_csv(path, decode_char(opts.get('delimiter',',')))
    h,d=split_header(rows, opts.get('no_headers'))
    ncols=len(h) if h is not None else (max([len(r) for r in rows] or [0]))
    idxs=parse_selection(opts['select'], h, ncols, bool(opts.get('no_headers'))) if 'select' in opts else list(range(ncols))
    out=[]
    if h is not None: out.append(h)
    for r in d:
        m=any(rx.search(row_get(r,i)) for i in idxs)
        if bool(opts.get('invert')): m=not m
        if m: out.append(r)
    write_csv(out, opts.get('output'))


def cmd_sort(argv):
    specs=common_specs({'-s':('select',True),'--select':('select',True),'-N':('numeric',False),'--numeric':('numeric',False),'-R':('reverse',False),'--reverse':('reverse',False)})
    opts,pos=parse_opts(argv,specs,'sort')
    if opts.get('help'): return print_cmd_help('sort')
    if len(pos)>1: invalid_args('sort')
    rows=read_csv(pos[0] if pos else None, decode_char(opts.get('delimiter',',')))
    h,d=split_header(rows, opts.get('no_headers'))
    ncols=len(h) if h is not None else (max([len(r) for r in rows] or [0]))
    idxs=parse_selection(opts['select'], h, ncols, bool(opts.get('no_headers'))) if 'select' in opts else list(range(ncols))
    if opts.get('numeric'):
        def key(r):
            vals=[]
            for i in idxs:
                s=row_get(r,i)
                try: vals.append((1, float(s)))
                except: vals.append((0, 0.0))
            return vals
    else:
        def key(r): return [row_get(r,i) for i in idxs]
    d=sorted(d, key=key, reverse=bool(opts.get('reverse')))
    out=[]
    if h is not None: out.append(h)
    out.extend(d)
    write_csv(out, opts.get('output'))


def cmd_frequency(argv):
    specs=common_specs({'-s':('select',True),'--select':('select',True),'-l':('limit',True),'--limit':('limit',True),'-a':('asc',False),'--asc':('asc',False),'--no-nulls':('no_nulls',False),'-j':('jobs',True),'--jobs':('jobs',True)})
    opts,pos=parse_opts(argv,specs,'frequency')
    if opts.get('help'): return print_cmd_help('frequency')
    if len(pos)>1: invalid_args('frequency')
    rows=read_csv(pos[0] if pos else None, decode_char(opts.get('delimiter',',')))
    h,d=split_header(rows, opts.get('no_headers'))
    ncols=len(h) if h is not None else (max([len(r) for r in rows] or [0]))
    names=h if h is not None else [str(i+1) for i in range(ncols)]
    idxs=parse_selection(opts['select'], h, ncols, bool(opts.get('no_headers'))) if 'select' in opts else list(range(ncols))
    limit=parse_int(opts.get('limit','10'),'--limit') if 'limit' in opts else 10
    out=[['field','value','count']]
    for i in idxs:
        c=Counter()
        for r in d:
            v=row_get(r,i)
            if v=='':
                if opts.get('no_nulls'): continue
                v='(NULL)'
            c[v]+=1
        items=list(c.items())
        # Target's tie order is hash-dependent; use value as stable approximation.
        items.sort(key=lambda kv: (kv[1], kv[0]) if opts.get('asc') else (-kv[1], kv[0]))
        if limit != 0: items=items[:limit]
        for v,n in items: out.append([names[i] if i < len(names) else str(i+1), v, str(n)])
    write_csv(out, opts.get('output'))


def cmd_flatten(argv):
    specs=common_specs({'-c':('condense',True),'--condense':('condense',True),'-s':('separator',True),'--separator':('separator',True)}, include_output=False)
    opts,pos=parse_opts(argv,specs,'flatten')
    if opts.get('help'): return print_cmd_help('flatten')
    if len(pos)>1: invalid_args('flatten')
    rows=read_csv(pos[0] if pos else None, decode_char(opts.get('delimiter',',')))
    h,d=split_header(rows, opts.get('no_headers'))
    if h is None:
        ncols=max([len(r) for r in rows] or [0]); labels=[str(i) for i in range(ncols)]
    else:
        labels=h
    width=max([len(x) for x in labels] or [0]) + 2
    cond=int(opts['condense']) if 'condense' in opts else None
    sep=opts.get('separator', '#')
    def condense(s): return s[:cond]+'...' if cond is not None and len(s)>cond else s
    out=[]
    for ri,r in enumerate(d):
        for i,lab in enumerate(labels):
            out.append(lab + (' ' * (width-len(lab))) + condense(row_get(r,i)))
        if sep != '' and ri != len(d)-1:
            out.append(sep)
    if out: sys.stdout.write('\n'.join(out)+'\n')


def cmd_table(argv):
    specs=common_specs({'-w':('width',True),'--width':('width',True),'-p':('pad',True),'--pad':('pad',True),'-c':('condense',True),'--condense':('condense',True)}, include_no_headers=False)
    opts,pos=parse_opts(argv,specs,'table')
    if opts.get('help'): return print_cmd_help('table')
    if len(pos)>1: invalid_args('table')
    rows=read_csv(pos[0] if pos else None, decode_char(opts.get('delimiter',',')))
    cond=int(opts['condense']) if 'condense' in opts else None
    if cond is not None:
        rows=[[x[:cond]+'...' if len(x)>cond else x for x in r] for r in rows]
    minw=int(opts.get('width','2')); pad=int(opts.get('pad','2'))
    n=max([len(r) for r in rows] or [0])
    widths=[minw]*n
    for r in rows:
        for i in range(n): widths[i]=max(widths[i], len(row_get(r,i)))
    lines=[]
    for r in rows:
        parts=[]
        for i in range(n):
            val=row_get(r,i)
            if i==n-1: parts.append(val)
            else: parts.append(val + ' '*(widths[i]-len(val)+pad))
        lines.append(''.join(parts))
    text='\n'.join(lines)
    if text: text+='\n'
    out,close=output_handle(opts.get('output')); out.write(text); 
    if close: out.close()


def cmd_fixlengths(argv):
    specs=common_specs({'-l':('length',True),'--length':('length',True)}, include_no_headers=False)
