    n1=len(h1) if h1 is not None else (max([len(r) for r in r1] or [0])); n2=len(h2) if h2 is not None else (max([len(r) for r in r2] or [0]))
    i1=parse_selection(c1,h1,n1,bool(opts.get('no_headers'))); i2=parse_selection(c2,h2,n2,bool(opts.get('no_headers')))
    if len(i1)!=len(i2): die('The same number of columns must be selected for each CSV data set.')
    out=[]
    if h1 is not None and h2 is not None: out.append(h1+h2)
    if opts.get('cross'):
        for a in d1:
            for b in d2: out.append(a+b)
        return write_csv(out, opts.get('output'))
    mp=defaultdict(list)
    valid2=[]
    for j,b in enumerate(d2):
        k=key_for(b,i2,opts.get('no_case'))
        if (not opts.get('nulls')) and any(x=='' for x in k): continue
        mp[k].append((j,b)); valid2.append(j)
    matched2=set()
    leftish=opts.get('left') or opts.get('full') or (not opts.get('right'))
    if leftish:
        for a in d1:
            k=key_for(a,i1,opts.get('no_case'))
            matches=[] if ((not opts.get('nulls')) and any(x=='' for x in k)) else mp.get(k,[])
            if matches:
                for j,b in matches:
                    matched2.add(j); out.append(a+b)
            elif opts.get('left') or opts.get('full'):
                out.append(a+['']*n2)
    if opts.get('right') and not opts.get('full'):
        # right join in right row order
        mp1=defaultdict(list)
        for a in d1:
            k=key_for(a,i1,opts.get('no_case'))
            if (not opts.get('nulls')) and any(x=='' for x in k): continue
            mp1[k].append(a)
        out = out[:1] if (h1 is not None and h2 is not None) else []
        for b in d2:
            k=key_for(b,i2,opts.get('no_case'))
            matches=[] if ((not opts.get('nulls')) and any(x=='' for x in k)) else mp1.get(k,[])
            if matches:
                for a in matches: out.append(a+b)
            else: out.append(['']*n1+b)
    elif opts.get('full'):
        for j,b in enumerate(d2):
            if j not in matched2: out.append(['']*n1+b)
    write_csv(out, opts.get('output'))


