    path=pos[0]; outp=opts.get('output', path+'.idx')
    delim=decode_char(opts.get('delimiter',','))
    # Create a simple compatible-looking offset table: big-endian u64 offsets for each record start plus EOF.
    offsets=[]; off=0
    try:
        with open(path,'rb') as f:
            data=f.read()
    except OSError as e: die(str(e))
    offsets.append(0)
    for i,b in enumerate(data):
        if b==10 and i+1 < len(data): offsets.append(i+1)
    offsets.append(len(data))
    with open(outp,'wb') as f:
        for x in offsets:
            f.write(int(x).to_bytes(8,'big'))


def dispatch(cmd, argv):
    table={
        'count':cmd_count,'headers':cmd_headers,'select':cmd_select,'slice':cmd_slice,'reverse':cmd_reverse,
        'search':cmd_search,'sort':cmd_sort,'frequency':cmd_frequency,'flatten':cmd_flatten,'table':cmd_table,
        'fixlengths':cmd_fixlengths,'fmt':cmd_fmt,'input':cmd_input,'cat':cmd_cat,'join':cmd_join,
        'partition':cmd_partition,'split':cmd_split,'sample':cmd_sample,'stats':cmd_stats,'index':cmd_index,
    }
    if cmd in table: return table[cmd](argv)
    if cmd == 'help': sys.stdout.write(TOP_HELP); return
    allowed=[c for c,_ in COMMANDS]
    die("Could not match '%s' with any of the allowed variants: %s" % (cmd, repr(allowed).replace("'", '"')))


def main(argv):
    if not argv or argv[0] in ('-h','--help','help'):
        sys.stdout.write(TOP_HELP); return
    if argv[0]=='--version': print(VERSION); return
    if argv[0]=='--list':
        sys.stdout.write('Installed commands:\n')
        sys.stdout.write('\n'.join('    %-11s %s' % (c,d) for c,d in COMMANDS)+'\n')
        return
    cmd=argv[0]
    if len(argv)>1 and argv[1] in ('-h','--help'):
        print_cmd_help(cmd); return
    dispatch(cmd, argv[1:])

if __name__ == '__main__':
    try:
        main(sys.argv[1:])
    except BrokenPipeError:
        try: sys.stderr.close()
        except Exception: pass
