def cmd_cat(argv):
    specs=common_specs({'-p':('pad',False),'--pad':('pad',False)})
    opts,pos=parse_opts(argv,specs,'cat')
    if opts.get('help'): return print_cmd_help('cat')
    if len(pos)<1: invalid_args('cat')
    mode=pos[0]; files=pos[1:]
    if mode not in ('rows','columns'): invalid_args('cat')
    delim=decode_char(opts.get('delimiter',','))
    if not files: files=[None]
    datasets=[read_csv(f,delim) for f in files]
    out=[]
    if mode=='rows':
        expected=None
        for di,rows in enumerate(datasets):
            for ri,r in enumerate(rows):
                if di>0 and ri==0 and not opts.get('no_headers'):
                    continue
                if expected is None: expected=len(r)
                elif len(r)!=expected:
                    # write partial then error, approximating xsv
                    write_csv(out, opts.get('output'))
                    die('CSV error: found record with %s fields, but the previous record has %s fields' % (len(r), expected))
                out.append(r)
    else:
        lens=[len(x) for x in datasets]
        n=max(lens) if opts.get('pad') else (min(lens) if lens else 0)
        for i in range(n):
            row=[]
            for rows in datasets:
                width=len(rows[0]) if rows else 0
                if i < len(rows): row.extend(rows[i])
                else: row.extend(['']*width)
            out.append(row)
    write_csv(out, opts.get('output'))


def key_for(row, idxs, no_case=False):
    vals=[]
    for i in idxs:
        v=row_get(row,i).strip()
        if no_case: v=v.lower()
        vals.append(v)
    return tuple(vals)


def cmd_join(argv):
    specs=common_specs({'--no-case':('no_case',False),'--left':('left',False),'--right':('right',False),'--full':('full',False),'--cross':('cross',False),'--nulls':('nulls',False)})
    opts,pos=parse_opts(argv,specs,'join')
    if opts.get('help'): return print_cmd_help('join')
    if len(pos)!=4: invalid_args('join')
    c1,p1,c2,p2=pos
    delim=decode_char(opts.get('delimiter',','))
    r1=read_csv(p1,delim); r2=read_csv(p2,delim)
    h1,d1=split_header(r1, opts.get('no_headers')); h2,d2=split_header(r2, opts.get('no_headers'))
    n1=len(h1) if h1 is not None else (max([len(r) for r in r1] or [0])); n2=len(h2) if h2 is not None else (max([len(r) for r in r2] or [0]))
    i1=parse_selection(c1,h1,n1,bool(opts.get('no_headers'))); i2=parse_selection(c2,h2,n2,bool(opts.get('no_headers')))
    if len(i1)!=len(i2): die('The same number of columns must be selected for each CSV data set.')
    out=[]
    if h1 is not None and h2 is not None: out.append(h1+h2)
    if opts.get('cross'):
        for a in d1:
            for b in d2: out.append(a+b)
        return write_csv(out, opts.get('output'))
    mp=defaultdict(list)
    valid2=[]
    for j,b in enumerate(d2):
        k=key_for(b,i2,opts.get('no_case'))
        if (not opts.get('nulls')) and any(x=='' for x in k): continue
        mp[k].append((j,b)); valid2.append(j)
    matched2=set()
    leftish=opts.get('left') or opts.get('full') or (not opts.get('right'))
    if leftish:
        for a in d1:
            k=key_for(a,i1,opts.get('no_case'))
            matches=[] if ((not opts.get('nulls')) and any(x=='' for x in k)) else mp.get(k,[])
            if matches:
                for j,b in matches:
                    matched2.add(j); out.append(a+b)
            elif opts.get('left') or opts.get('full'):
                out.append(a+['']*n2)
    if opts.get('right') and not opts.get('full'):
        # right join in right row order
        mp1=defaultdict(list)
        for a in d1:
            k=key_for(a,i1,opts.get('no_case'))
            if (not opts.get('nulls')) and any(x=='' for x in k): continue
            mp1[k].append(a)
        out = out[:1] if (h1 is not None and h2 is not None) else []
        for b in d2:
            k=key_for(b,i2,opts.get('no_case'))
            matches=[] if ((not opts.get('nulls')) and any(x=='' for x in k)) else mp1.get(k,[])
            if matches:
                for a in matches: out.append(a+b)
            else: out.append(['']*n1+b)
    elif opts.get('full'):
        for j,b in enumerate(d2):
            if j not in matched2: out.append(['']*n1+b)
    write_csv(out, opts.get('output'))


def sanitize_filename(v):
    s=''.join(ch for ch in v if ch.isalnum() or ch in '._-')
    return s if s else 'empty'


def cmd_partition(argv):
    specs=common_specs({'--filename':('filename',True),'-p':('prefix_length',True),'--prefix-length':('prefix_length',True),'--drop':('drop',False)}, include_output=False)
    opts,pos=parse_opts(argv,specs,'partition')
    if opts.get('help'): return print_cmd_help('partition')
    if len(pos)<2 or len(pos)>3: invalid_args('partition')
    col,outdir=pos[0],pos[1]; path=pos[2] if len(pos)>2 else None
    rows=read_csv(path, decode_char(opts.get('delimiter',',')))
    h,d=split_header(rows, opts.get('no_headers'))
    ncols=len(h) if h is not None else (max([len(r) for r in rows] or [0]))
    idx=parse_selection(col,h,ncols,bool(opts.get('no_headers')))[0]
    os.makedirs(outdir, exist_ok=True)
    groups=defaultdict(list); order=[]
    for r in d:
        val=row_get(r,idx)
        if 'prefix_length' in opts: val=val[:int(opts['prefix_length'])]
        name=(opts.get('filename','{}.csv')).replace('{}', sanitize_filename(val))
        if name not in groups: order.append(name)
        rr=list(r)
        if opts.get('drop') and idx < len(rr): rr=rr[:idx]+rr[idx+1:]
        groups[name].append(rr)
    header=None
    if h is not None:
        header=list(h)
        if opts.get('drop'): header=header[:idx]+header[idx+1:]
    for name in order:
        out=[]
        if header is not None: out.append(header)
        out.extend(groups[name])
        write_csv(out, os.path.join(outdir,name))


def cmd_split(argv):
    specs=common_specs({'-s':('size',True),'--size':('size',True),'-j':('jobs',True),'--jobs':('jobs',True),'--filename':('filename',True)}, include_output=False)
