    tmpl=opts.get('filename','{}.csv')
    for start in range(0,len(d),size):
        out=[]
        if h is not None: out.append(h)
        out.extend(d[start:start+size])
        write_csv(out, os.path.join(outdir, tmpl.replace('{}', str(start))))


def cmd_sample(argv):
    specs=common_specs({'--seed':('seed',True)})
    opts,pos=parse_opts(argv,specs,'sample')
    if opts.get('help'): return print_cmd_help('sample')
    if len(pos)<1 or len(pos)>2: invalid_args('sample')
    k=int(pos[0]); path=pos[1] if len(pos)>1 else None
    rows=read_csv(path, decode_char(opts.get('delimiter',',')))
    h,d=split_header(rows, opts.get('no_headers'))
    rnd=random.Random(int(opts['seed']) if 'seed' in opts else None)
    if k >= len(d): sample=list(d)
    else:
        sample=[]
        for i,row in enumerate(d):
            if i < k: sample.append(row)
            else:
                j=rnd.randrange(i+1)
                if j < k: sample[j]=row
        rnd.shuffle(sample)
    out=[]
    if h is not None: out.append(h)
    out.extend(sample)
    write_csv(out, opts.get('output'))


def type_and_nums(vals):
    nonnull=[v for v in vals if v!='']
    ints=[]; floats=[]
    all_int=True; all_num=True
    for v in nonnull:
        try:
            if re.fullmatch(r'[+-]?\d+', v):
                ints.append(int(v)); floats.append(float(int(v)))
            else:
                all_int=False; floats.append(float(v))
        except:
            all_num=False; all_int=False; break
    if nonnull and all_num:
        return ('Integer' if all_int else 'Float', floats)
    return ('Unicode', [])


def fmt_num(x):
    if x == '': return ''
    if isinstance(x,float):
        if math.isnan(x): return ''
        if abs(x-round(x)) < 1e-12: return str(int(round(x)))
        return repr(x)
    return str(x)


def cmd_stats(argv):
    specs=common_specs({'-s':('select',True),'--select':('select',True),'--everything':('everything',False),'--mode':('mode',False),'--cardinality':('cardinality',False),'--median':('median',False),'--nulls':('nulls',False),'-j':('jobs',True),'--jobs':('jobs',True)})
    opts,pos=parse_opts(argv,specs,'stats')
    if opts.get('help'): return print_cmd_help('stats')
    if len(pos)>1: invalid_args('stats')
    rows=read_csv(pos[0] if pos else None, decode_char(opts.get('delimiter',',')))
    h,d=split_header(rows, opts.get('no_headers'))
    ncols=len(h) if h is not None else (max([len(r) for r in rows] or [0]))
    names=h if h is not None else [str(i+1) for i in range(ncols)]
    idxs=parse_selection(opts['select'], h, ncols, bool(opts.get('no_headers'))) if 'select' in opts else list(range(ncols))
    want_median=opts.get('median') or opts.get('everything')
    want_mode=opts.get('mode') or opts.get('everything')
    want_card=opts.get('cardinality') or opts.get('everything')
    header=['field','type','sum','min','max','min_length','max_length','mean','stddev']
    if want_median: header.append('median')
    if want_mode: header.append('mode')
    if want_card: header.append('cardinality')
    out=[header]
    for i in idxs:
        vals=[row_get(r,i) for r in d]
        typ, nums=type_and_nums(vals)
        nonnull=[v for v in vals if v!='']
        lengths=[len(v) for v in vals]
        minlen=min(lengths) if lengths else 0; maxlen=max(lengths) if lengths else 0
        mn=min(nonnull) if nonnull else ''; mx=max(nonnull) if nonnull else ''
        sumv=mean=std=''
        med=''
        if typ in ('Integer','Float'):
            sumv=sum(nums)
            denom_vals=nums
            denom_len=len(vals) if opts.get('nulls') else len(nums)
            if denom_len:
                mean=sum(nums)/denom_len
                if denom_len>1:
                    # sample stddev with nulls as zero when requested (matching observed roughly)
                    arr=nums + ([0.0]*(len(vals)-len(nums)) if opts.get('nulls') else [])
                    if len(arr)>1: std=statistics.stdev(arr)
                elif denom_len==1: std=0
            if want_median and nums: med=statistics.median(nums)
        else:
            # xsv reports median for mixed unicode from numeric-looking values; approximate.
            if want_median:
                numeric=[]
                for v in nonnull:
                    try: numeric.append(float(v))
                    except: pass
                if numeric: med=statistics.median(numeric)
        row=[names[i] if i<len(names) else str(i+1), typ, fmt_num(sumv), mn, mx, str(minlen), str(maxlen), fmt_num(mean), fmt_num(std)]
        if want_median: row.append(fmt_num(med))
        if want_mode:
            if vals:
                c=Counter(vals); maxc=max(c.values()) if c else 0; modes=[k for k,v in c.items() if v==maxc]
                row.append(modes[0] if len(modes)==1 and modes[0] != '' else ('N/A' if len(modes)>1 else ''))
            else: row.append('')
        if want_card: row.append(str(len(set(vals))))
        out.append(row)
    write_csv(out, opts.get('output'))


def cmd_index(argv):
    opts,pos=parse_opts(argv, common_specs({'-o':('output',True),'--output':('output',True)}, include_no_headers=False), 'index')
    if opts.get('help'): return print_cmd_help('index')
    if len(pos)!=1: invalid_args('index')
    path=pos[0]; outp=opts.get('output', path+'.idx')
    delim=decode_char(opts.get('delimiter',','))
    # Create a simple compatible-looking offset table: big-endian u64 offsets for each record start plus EOF.
    offsets=[]; off=0
    try:
        with open(path,'rb') as f:
            data=f.read()
    except OSError as e: die(str(e))
    offsets.append(0)
    for i,b in enumerate(data):
        if b==10 and i+1 < len(data): offsets.append(i+1)
    offsets.append(len(data))
    with open(outp,'wb') as f:
        for x in offsets:
            f.write(int(x).to_bytes(8,'big'))


def dispatch(cmd, argv):
    table={
        'count':cmd_count,'headers':cmd_headers,'select':cmd_select,'slice':cmd_slice,'reverse':cmd_reverse,
        'search':cmd_search,'sort':cmd_sort,'frequency':cmd_frequency,'flatten':cmd_flatten,'table':cmd_table,
        'fixlengths':cmd_fixlengths,'fmt':cmd_fmt,'input':cmd_input,'cat':cmd_cat,'join':cmd_join,
        'partition':cmd_partition,'split':cmd_split,'sample':cmd_sample,'stats':cmd_stats,'index':cmd_index,
    }
    if cmd in table: return table[cmd](argv)
    if cmd == 'help': sys.stdout.write(TOP_HELP); return
    allowed=[c for c,_ in COMMANDS]
    die("Could not match '%s' with any of the allowed variants: %s" % (cmd, repr(allowed).replace("'", '"')))


def main(argv):
    if not argv or argv[0] in ('-h','--help','help'):
        sys.stdout.write(TOP_HELP); return
    if argv[0]=='--version': print(VERSION); return
    if argv[0]=='--list':
        sys.stdout.write('Installed commands:\n')
        sys.stdout.write('\n'.join('    %-11s %s' % (c,d) for c,d in COMMANDS)+'\n')
        return
    cmd=argv[0]
    if len(argv)>1 and argv[1] in ('-h','--help'):
        print_cmd_help(cmd); return
    dispatch(cmd, argv[1:])

if __name__ == '__main__':
    try:
        main(sys.argv[1:])
    except BrokenPipeError:
        try: sys.stderr.close()
        except Exception: pass
